"""Feature gate dictionary combiner."""
from typing import Dict, Any, List

def _deduplicate_list(lst: List[Any]) -> List[Any]:
    """Removes duplicates from a list while preserving first-seen order."""
    seen = set()
    result = []
    for item in lst:
        if item not in seen:
            seen.add(item)
            result.append(item)
    return result

def combine_gate_dicts(base: Dict[str, Any], override: Dict[str, Any]) -> Dict[str, Any]:
    """Combines gate dictionaries."""
    res = dict(base)
    for k, v in override.items():
        if k in res and isinstance(res[k], dict) and isinstance(v, dict):
            res[k] = combine_gate_dicts(res[k], v)
        elif k in res and isinstance(res[k], list) and isinstance(v, list):
            # Rule H12: Concatenate lists and deduplicate preserving first-seen order.
            combined_list = res[k] + v
            res[k] = _deduplicate_list(combined_list)
        else:
            # For other types, or if key is new, or types don't match for special merge,
            # simply replace/add the value.
            res[k] = v
    return res

def is_valid_gate_key(key: str) -> bool:
    return bool(key and isinstance(key, str))
